param([string]$Output=(Join-Path $env:TEMP "GManager-Support-$((Get-Date).ToUniversalTime().ToString('yyyyMMddTHHmmssZ')).zip"))
$ErrorActionPreference='Stop';$work=Join-Path $env:TEMP ([Guid]::NewGuid());New-Item $work -ItemType Directory|Out-Null;try{$service=Get-CimInstance Win32_Service -Filter "Name='GManagerClient'"|Select-Object Name,State,StartMode,ExitCode;$service|ConvertTo-Json|Set-Content (Join-Path $work 'service.json');Get-ChildItem (Join-Path $env:ProgramFiles 'GManager Client') -Recurse -File|Where-Object Extension -in '.exe','.dll'|Select-Object Name,@{n='Version';e={$_.VersionInfo.FileVersion}},@{n='Sha256';e={(Get-FileHash $_.FullName).Hash}}|ConvertTo-Json|Set-Content (Join-Path $work 'files.json');Get-WinEvent -FilterHashtable @{LogName='Application';StartTime=(Get-Date).AddDays(-2)} -ErrorAction SilentlyContinue|Where-Object ProviderName -like 'GManager*'|Select-Object TimeCreated,Id,LevelDisplayName,ProviderName|ConvertTo-Json|Set-Content (Join-Path $work 'events.json');$operations=Join-Path $env:ProgramData 'GManager\Client\operational.jsonl';if(Test-Path $operations){Get-Content $operations -Tail 1000|Set-Content (Join-Path $work 'operational.jsonl')};Compress-Archive (Join-Path $work '*') $Output -Force;Write-Output $Output}finally{Remove-Item $work -Recurse -Force}
